#include <npp.h>
#include <nppi.h>
#include <cuda_runtime.h>
#include <stdio.h>

#define CUDA_CHECK(call) { cudaError_t err = call; if (err != cudaSuccess) { fprintf(stderr, "CUDA error: %s at %s:%d\n", cudaGetErrorString(err), __FILE__, __LINE__); exit(1); } }
#define NPP_CHECK(call) { NppStatus err = call; if (err != NPP_SUCCESS) { fprintf(stderr, "NPP error %d at %s:%d\n", err, __FILE__, __LINE__); exit(1); } }

void gpu_resize_image(const unsigned char* h_src, int src_w, int src_h,
                      unsigned char* h_dst, int dst_w, int dst_h, int channels) {
    // Allocate GPU memory
    size_t src_pitch, dst_pitch;
    Npp8u *d_src, *d_dst;
    CUDA_CHECK(cudaMallocPitch(&d_src, &src_pitch, src_w * channels, src_h));
    CUDA_CHECK(cudaMallocPitch(&d_dst, &dst_pitch, dst_w * channels, dst_h));

    // Upload
    CUDA_CHECK(cudaMemcpy2D(d_src, src_pitch, h_src, src_w * channels,
                            src_w * channels, src_h, cudaMemcpyHostToDevice));

    // Resize
    NppiSize srcSize = {src_w, src_h};
    NppiRect srcROI = {0, 0, src_w, src_h};
    NppiSize dstSize = {dst_w, dst_h};
    NppiRect dstROI = {0, 0, dst_w, dst_h};
    NPP_CHECK(nppiResize_8u_C3R(d_src, src_pitch, srcSize, srcROI,
                                d_dst, dst_pitch, dstSize, dstROI,
                                NPPI_INTER_LINEAR));

    // Download
    CUDA_CHECK(cudaMemcpy2D(h_dst, dst_w * channels, d_dst, dst_pitch,
                            dst_w * channels, dst_h, cudaMemcpyDeviceToHost));

    cudaFree(d_src); cudaFree(d_dst);
}
